const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem('petaccess-'+key))??fallback}catch{return fallback}}
function persist(key,val){try{localStorage.setItem('petaccess-'+key,JSON.stringify(val))}catch{}}
const state={tab:'home',category:'all',map:false,query:'',freeKind:'all',checkins:read('checkins',[]),filters:[],saved:read('saved',[]),route:read('route',null),bookings:read('bookings',[]),pet:read('pet',{name:'豆包',breed:'金毛',size:'大型犬'}),modal:null,selectedCafe:'cafe',selectedPark:'park',chatQuery:'',chatReady:false,navStep:1};
function petContext(){return `<div class="pet-context"><img src="${photoSrc('golden')}" alt="我的宠物">${esc(state.pet.name)} · ${esc(state.pet.breed)} · ${esc(state.pet.size)} <button data-action="pet" aria-label="编辑宠物档案">${icon('edit')}</button></div>`}
const freeKinds={park:'宠物友好公园',trail:'郊野步道',green:'公共开放绿地',public:'携宠公共空间'};
function latestCheckin(id){return state.checkins.filter(c=>c.place===id).sort((a,b)=>b.visited.localeCompare(a.visited)||b.id-a.id)[0]}
function canPlan(p){return p&&(!p.small||state.pet.size==='小型犬')&&latestCheckin(p.id)?.access!=='no'}
function freeFacts(p){const report=latestCheckin(p.id);return `<div class="free-facts"><span>${esc(freeKinds[p.kind])}</span><span class="${report?.access==='no'?'needs-check':''}">${report?report.access==='yes'?'本机打卡 · 可携宠':report.access==='no'?'现场有变 · 建议核实':'本机反馈 · 待核实':'示例信息 · 出发前核实'}</span></div>`}
function freeExplore(){return `<section class="free-explore" aria-label="免费遛狗地点类型"><div class="free-lead">${icon('leaf')}<div><strong>日常遛狗，也值得好好出门。</strong><p>免费公共点位 · 无需预约</p></div></div><div class="free-kinds">${[['all','全部点位'],...Object.entries(freeKinds)].map(([key,label])=>`<button class="free-kind ${state.freeKind===key?'active':''}" data-action="free-kind" data-value="${key}" aria-pressed="${state.freeKind===key}">${label}</button>`).join('')}</div><p class="free-hint">先看可携宠范围，再出发。现场规则有变化？打卡告诉下一位宠友。</p></section>`}
function freeDetail(p){const report=latestCheckin(p.id);return `<section class="free-detail"><div class="free-detail-heading"><span>${freeKinds[p.kind]}</span><span>免费公共点位</span></div><h3>这次散步，先了解这些</h3><dl><div><dt>可携宠范围</dt><dd>${esc(p.area)}</dd></div><div><dt>路面情况</dt><dd>${esc(p.surface)}</dd></div><div><dt>宠物条件</dt><dd>${p.small?'暂仅小型犬':'大小型犬均可'} · 全程牵引</dd></div><div><dt>饮水设施</dt><dd>${p.water?'示例设有饮水设施，建议仍自备水':'请自备宠物饮水'}</dd></div></dl><p class="free-source">示例收录，未经实地核实 · 以现场公示为准</p></section><section class="checkin-panel"><div class="checkin-heading"><div><p class="section-kicker">PAWS ON THE GROUND</p><h3>让下一位宠友少走弯路</h3></div>${icon('paw')}</div><p>记录今天能否携宠、开放区域或设施变化。</p>${report?`<div class="local-checkin"><strong>${report.access==='yes'?'可携宠':report.access==='no'?'现场有变化，暂不推荐前往':'携宠规则待核实'}</strong><span>${esc(report.visited)} · 我的本机打卡</span>${report.note?`<p>${esc(report.note)}</p>`:''}<small>${report.access==='no'?'暂不纳入新规划的路线，待现场重新确认。':'个人反馈供参考，出发前仍需核实。'}</small></div>`:''}<button class="secondary" data-action="checkin" data-id="${p.id}">${icon('edit')}${report?'补充打卡 / 纠错':'我来打卡 / 纠错'}</button></section>`}
function checkinSheet(id){const p=places.find(p=>p.id===id);if(!p?.free)return;state.checkinId=id;state.modal='checkin';const today=new Date().toLocaleDateString('sv-SE');sheet(`<div class="sheet-body">${sheetHead('记录这次，带它来过')}<p class="checkin-place">${icon('pin')}${esc(p.name)}</p><form id="checkin-form"><div class="form-field"><label for="visit-date">到访日期</label><input id="visit-date" name="visited" type="date" value="${today}" max="${today}" required></div><fieldset class="checkin-choices"><legend>现场可以携宠吗？</legend>${[['yes','可以携宠','按现场规则正常通行'],['no','现场有变','禁止携宠、关闭或范围调整'],['unsure','暂不确定','没有找到明确标识或需再核实']].map(([value,title,desc])=>`<label><input type="radio" name="access" value="${value}" required><span><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}</fieldset><div class="form-field"><label for="visit-note">补充现场情况（选填）</label><textarea id="visit-note" name="note" maxlength="140" rows="3" placeholder="例如：东侧草坪关闭，请从南门步道进入。"></textarea></div><p class="notice">演示打卡仅保存在当前浏览器，不会公开发布，也未同步给其他用户。</p><button class="primary" type="submit">保存这次打卡${icon('check')}</button></form></div>`)}
function submitCheckin(form){const data=Object.fromEntries(new FormData(form));if(!['yes','no','unsure'].includes(data.access))return;const id=state.checkinId;state.checkins.unshift({id:Date.now(),place:id,access:data.access,visited:data.visited,note:data.note.trim()});persist('checkins',state.checkins);render();detail(id);toast('打卡已保存在本机，点位状态已更新')}
function routeOptions(id){const p=places.find(p=>p.id===id);if(!canPlan(p)){toast(p.small&&state.pet.size!=='小型犬'?'该点位暂仅小型犬友好，请选择适合它的地点':'该点位有现场变化反馈，请核实后再规划');return}state.modal='route-options';sheet(`<div class="sheet-body">${sheetHead('这次，想怎么散步？')}<p class="checkin-place">${icon('pin')}从 ${esc(p.name)} 出发</p><button class="route-option" data-action="start-free-route" data-id="${p.id}">${icon('tree')}<span><strong>只逛免费地点</strong><small>串起两个公共点位，无需预约</small></span>${icon('chevron')}</button><button class="route-option" data-action="start-cafe-route" data-id="${p.id}">${icon('coffee')}<span><strong>散完步，再喝杯咖啡</strong><small>免费点位 + 友好咖啡馆，套餐可选</small></span>${icon('chevron')}</button><p class="notice">路线基于示例地点生成，出发前请核实开放状态与携宠规则。</p></div>`)}
function matchesSearch(p){
 const aliases=p.type==='cafe'?'咖啡 咖啡馆 咖啡店 cafe coffee':`${freeKinds[p.kind]} 免费 遛狗 散步 ${p.kind==='park'?'公园 park':p.kind==='trail'?'郊野 步道 徒步 trail':p.kind==='green'?'草地 绿地 green':'广场 公共空间 public'}`;
 const haystack=[p.name,p.headline,p.address,...p.tags,aliases,...(state.category==='deals'?[packageInfo.title,packageInfo.food,packageInfo.pet,'套餐 下午茶']:[])].join(' ').toLowerCase();
 return state.query.toLowerCase().split(/\s+/).filter(Boolean).every(word=>haystack.includes(word));
}
function filteredPlaces(){return places.filter(p=>(state.category==='all'||state.category==='free'&&p.free||state.category==='deals'&&!p.free||p.type===state.category)&&(state.category!=='free'||state.freeKind==='all'||p.kind===state.freeKind)&&matchesSearch(p)&&state.filters.every(f=>f==='大型犬友好'?!p.small:f==='露台座位'?p.terrace:f==='提供水碗'?p.water:f==='2 km 内'?+p.distance<=2:f==='免费点位'?p.free:true))}
function card(p){return `<article class="place-card"><div class="card-image-wrap"><button class="photo" data-action="detail" data-id="${p.id}" aria-label="查看${p.name}"><img src="${photoSrc(p.image)}" alt="${p.name}氛围示意图" loading="lazy"><span class="place-kind ${p.free?'':'cafe'}">${icon(p.free?'tree':'coffee')}${p.free?freeKinds[p.kind]:'宠物友好咖啡'}</span>${p.ad?'<span class="ad-label">广告</span>':''}</button><button class="photo-save ${state.saved.includes(p.id)?'saved':''}" data-action="save-place" data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'取消收藏':'收藏'}${p.name}" aria-pressed="${state.saved.includes(p.id)}">${icon('heart')}</button></div><div class="card-info" role="button" tabindex="0" data-action="detail" data-id="${p.id}"><h3>${p.name}<span class="card-headline">${p.headline}</span></h3><div class="card-meta"><span class="star">★ ${p.rating}</span><span>·</span>${p.distance} km</div><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div>${p.free?freeFacts(p):''}<div class="card-bottom"><span class="card-price ${p.free?'free':''}">${p.free?'免费开放':`¥ <b>${p.price}</b> <span>/ 套餐</span>`}</span><span class="checkin"><img src="${photoSrc('dog')}" alt="">${p.reviews} 人来过</span></div></div></article>`}
function grid(items){if(!items.length)return '<div class="no-results">暂时没有符合条件的地点<br>换个条件，发现更多好去处<button class="secondary" data-action="reset-filters">清除筛选</button></div>';return `<div class="grid"><div class="column">${items.filter((_,i)=>i%2===0).map(card).join('')}</div><div class="column">${items.filter((_,i)=>i%2===1).map(card).join('')}</div></div>`}
function searchbox(){return `<form class="searchbox" id="search-form" role="search">${icon('search')}<input type="search" name="search" aria-label="搜索地点" aria-controls="discover-results" enterkeyhint="search" autocomplete="off" placeholder="搜索地点、咖啡馆、遛狗地" value="${esc(state.query)}"><button class="search-clear" type="button" data-action="clear-search" aria-label="清空搜索" ${state.query?'':'hidden'}>${icon('close')}</button><button class="search-submit" type="submit">搜索</button></form>`}
function syncSearchView(){
 const active=state.tab==='home'&&!!state.query;
 $('#page').classList.toggle('is-searching',active);
 if(state.tab!=='home')return;
 $('#discover-title').textContent=active?'搜索结果':categoryTitle();
 $('.section-kicker').textContent=active?'FIND YOUR NEXT STOP':state.category==='free'?'A LITTLE MORE GREEN':state.category==='cafe'?'COFFEE, WITH COMPANY':state.category==='deals'?'A TABLE FOR YOU BOTH':'NEARBY & PAW-FRIENDLY';
 $('.search-clear').hidden=!$('#search-form input').value;
}
function updateSearch(input,submitted=false){
 state.query=input.value.trim();
 syncSearchView();
 $('#discover-results').innerHTML=resultsHTML();
 $('#discover-status').textContent=state.query?`搜索“${state.query}”，找到 ${filteredPlaces().length} ${state.category==='deals'?'份套餐':'个地点'}`:'已清空搜索';
 if(submitted){
  input.blur();
  $('#page').scrollTop=0;
  toast(state.query?`已找到 ${filteredPlaces().length} ${state.category==='deals'?'份套餐':'个地点'}`:'输入地点名称，或试试“咖啡”“遛狗”');
 }
}
function mapHTML(items=places){return `<div class="mapbox"><svg viewBox="0 0 360 360" preserveAspectRatio="none" aria-label="福田地点分布示意图"><rect width="360" height="360" fill="#e9eedf"/><path d="M0 50 85 60 102 0h90l-18 110 110-10 76 25v100l-76-35-116 2-13 168H49L60 203 0 192Z" fill="#f4f3eb"/><path d="m0 288 130-40 230 35v45l-230-34L0 334Z" fill="#c9dbd5"/><path d="m-20 128 400 18M124-20 96 390M278-20 225 390M-20 225l400-25" stroke="#fff" stroke-width="14"/><path d="m-20 128 400 18M124-20 96 390M278-20 225 390M-20 225l400-25" stroke="#dbddce" stroke-width="1"/><path d="M155 270 178 250 198 221 216 207 235 142" stroke="#79926a" stroke-width="3" stroke-dasharray="5 5" fill="none"/><text x="145" y="80" fill="#acb49f" font-size="17" letter-spacing="6">福田区</text><text x="22" y="313" fill="#8fab9e" font-size="9" transform="rotate(-12 22 313)">深圳河</text><text x="155" y="130" fill="#a4aa95" font-size="7">香蜜湖路</text><text x="10" y="220" fill="#a4aa95" font-size="7">滨河大道</text></svg>${items.map((p,i)=>`<button class="map-pin ${p.id===state.selectedPark?'selected':''}" style="top:${[65,32,14,46,54,40,23][places.indexOf(p)]}%;left:${[10,49,12,41,4,16,42][places.indexOf(p)]}%" data-action="detail" data-id="${p.id}">${icon(p.free?'tree':'coffee')}${p.name}</button>`).join('')}<span class="map-you"></span><span class="map-disclaimer">位置为交互示意 · 非真实地图</span></div>`}
function listCard(p,action='detail'){return `<button class="list-card" data-action="${action}" data-id="${p.id}"><img src="${photoSrc(p.image)}" alt="${p.name}"><div><h3>${p.name}</h3><p>★ ${p.rating} · 距你 ${p.distance} km</p><p>${p.tags.join(' · ')}</p><span class="price">${p.free?'免费开放':`¥${p.price} / 套餐`}</span></div>${icon('chevron')}</button>`}
function home(){return `<header class="header"><div class="logo"><span class="brandmark">${brandLogo()}</span><span class="wordmark">Pet<span>Access</span></span></div><button class="location" data-action="location">${icon('pin')}深圳 · 福田${icon('down')}</button></header>${searchbox()}<button class="hero" data-action="category" data-value="free"><img src="${photoSrc('golden')}" alt="叼着郁金香的金毛犬"><div class="hero-content"><div class="tiny-label">GOOD DAYS, WITH PAWS.</div><h1>好天气，<br>要和它一起浪费。</h1><p>每一段出门的路，都有它的位置。</p><span class="hero-cta">找到今天的免费遛狗地${icon('arrow')}</span></div><span class="hero-edition">周末灵感 · 01</span></button><div class="quicklinks"><button class="quicklink" aria-pressed="${state.category==='free'}" data-action="category" data-value="free"><span class="quickicon">${categoryIcon('park')}</span>免费遛狗地<span class="category-check" aria-hidden="true">${icon('check')}</span></button><button class="quicklink" aria-pressed="${state.category==='cafe'}" data-action="category" data-value="cafe"><span class="quickicon">${categoryIcon('cafe')}</span>友好咖啡馆<span class="category-check" aria-hidden="true">${icon('check')}</span></button><button class="quicklink" data-action="ai"><span class="quickicon">${categoryIcon('route')}</span>AI 规划路线</button><button class="quicklink" aria-pressed="${state.category==='deals'}" data-action="deals"><span class="quickicon">${categoryIcon('deals')}</span>人宠好套餐<span class="category-check" aria-hidden="true">${icon('check')}</span></button></div><div class="section-head"><div><p class="section-kicker">${state.category==='free'?'A LITTLE MORE GREEN':state.category==='cafe'?'COFFEE, WITH COMPANY':state.category==='deals'?'A TABLE FOR YOU BOTH':'NEARBY &amp; PAW-FRIENDLY'}</p><h2 id="discover-title">${categoryTitle()}</h2></div>${state.category==='deals'?'<span class="deals-badge">到店享用</span>':`<button class="view-toggle" data-action="toggle-map">${icon(state.map?'home':'map')}${state.map?'列表模式':'地图模式'}</button>`}</div>${state.category==='free'?freeExplore():''}<div class="filter-row"><button class="chip ${state.category==='all'?'active':''}" data-action="${state.category==='free'?'reset-filters':'category'}" data-value="all" aria-pressed="${state.category==='all'}">${state.category==='free'?'重置':state.category==='all'?'推荐':'全部'}</button><button class="chip ${state.filters.includes('大型犬友好')?'active':''}" data-action="quick-filter" data-value="大型犬友好">大型犬友好</button><button class="chip ${state.filters.includes(state.category==='free'?'2 km 内':'露台座位')?'active':''}" data-action="quick-filter" data-value="${state.category==='free'?'2 km 内':'露台座位'}">${state.category==='free'?'2 km 内':'露台座位'}</button><button class="chip ${state.filters.includes('提供水碗')?'active':''}" data-action="quick-filter" data-value="提供水碗">提供水碗</button><button class="chip filter ${state.filters.length?'active':''}" data-action="filters" aria-label="更多筛选">${icon('filter')}${state.filters.length||''}</button></div><div id="discover-results">${resultsHTML()}</div><p class="subtle-note">每一次出门，都有新的小确幸<br>商家与点位均为演示 · 图片为氛围示意</p>`}
function categoryTitle(){return state.category==='free'?'免费遛狗地':state.category==='cafe'?'友好咖啡馆':state.category==='deals'?'人宠好套餐':'附近的好去处'}
function dealCard(p){const compatible=!p.small||state.pet.size==='小型犬';return `<article class="deal-card" data-place="${p.id}"><div class="deal-top"><button class="deal-photo" data-action="detail" data-id="${p.id}" aria-label="查看${p.name}门店"><img src="${photoSrc(p.image)}" alt="${p.name}门店氛围" loading="lazy">${p.ad?'<span class="ad-label">广告</span>':''}</button><div class="deal-heading"><p class="deal-type">携宠到店 · 双人套餐</p><h3>${packageInfo.title}</h3><button class="deal-merchant" data-action="detail" data-id="${p.id}" aria-label="查看${p.name}门店">${p.name}${icon('chevron')}</button><p class="deal-distance">距你 ${p.distance} km · ${p.small?'仅小型犬':'大型犬友好'}</p></div></div><div class="deal-inclusions"><p><span>人的下午茶</span>${packageInfo.food}</p><p><span>毛孩子同行</span>${packageInfo.pet}</p></div><div class="deal-bottom"><span class="deal-price">¥<strong>${p.price}</strong><span> / 份 · 2 人</span></span><button class="primary" data-action="booking" data-id="${p.id}" ${compatible?'':'disabled'} aria-label="${compatible?'预约'+p.name+'套餐':'仅接待小型犬'}">${compatible?'预约套餐':'仅接待小型犬'}${compatible?icon('arrow'):''}</button></div></article>`}
function resultsHTML(){let ps=filteredPlaces();const deals=state.category==='deals';return `${deals?'<p class="deals-intro">由宠物友好咖啡馆提供，先看套餐，再选门店。<br>包含人的餐饮与携宠服务，暂不含宠物餐食。</p>':''}${state.category!=='all'||state.query||state.filters.length?`<div class="results-meta"><span>${state.query?`<span class="search-query">“${esc(state.query)}”</span><span class="search-scope">${categoryTitle()}${state.category==='free'&&state.freeKind!=='all'?` · ${freeKinds[state.freeKind]}`:''}${state.filters.length?` · ${state.filters.length} 项筛选`:''}</span>`:""}找到 <strong>${ps.length}</strong> ${state.category==='free'?'处免费遛狗地':state.category==='cafe'?'家友好咖啡馆':deals?'份到店套餐':'个好去处'}</span><button data-action="reset-filters">查看全部${icon('arrow')}</button></div>`:''}${deals?(ps.length?`<div class="deals-list">${ps.map(dealCard).join('')}</div>`:grid([])):state.map&&ps.length?mapHTML(ps)+ps.map(p=>listCard(p)).join(''):grid(ps)}`}
function selectCategory(value,source){
 const changed=state.category!==value;
 state.category=value;state.freeKind='all';if(value==='free')state.filters=state.filters.filter(f=>f!=='露台座位');state.map=false;state.tab='home';render();
 // Keep the chosen category in view and preserve keyboard focus across rendering.
 const selector=source==='quick'?`.quicklink[data-value="${value}"]`:source==='deals'?'.quicklink[data-action="deals"]':'.chip[data-value="all"]';
 document.querySelector(selector)?.focus({preventScroll:true});
 if(changed&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
  $('#discover-results').animate([{opacity:.35,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:200,easing:'ease-out'});
 }
 $('#discover-status').textContent=`已切换到${categoryTitle()}，找到 ${filteredPlaces().length} ${value==='deals'?'份套餐':'个好去处'}`;
}
function itinerary(){if(!state.route)return `<h1 class="page-title">一起出发的计划</h1><p class="page-desc">把想去的地方，串成属于你们的路线。</p><div class="empty-state">${icon('route')}<h3>下一次小冒险，去哪儿？</h3><p>告诉 AI 你想怎么度过这个下午，<br>从遛狗到喝咖啡，都为你安排好。</p><button class="primary" data-action="ai">${icon('spark')}让 AI 帮我规划</button></div>`;let p=places.find(p=>p.id===state.route.park),c=places.find(p=>p.id===state.route.cafe);return `<h1 class="page-title">一起出发的计划</h1><p class="page-desc">不赶时间，只管和它一起享受。</p><div class="itinerary-card"><div class="itinerary-cover"><img src="${photoSrc('park')}" alt="散步草地"><div><h3>和它一起，半日慢游</h3><p>深圳 · 福田 / 约 3 小时 / 2 个地点</p></div></div><div class="itinerary-body">${routeStops(p,c,false)}<div class="itinerary-buttons"><button class="secondary" data-action="ai">修改路线</button><button class="primary" data-action="navigation">${icon('route')}查看路线</button></div></div></div><p class="notice">已保存在这台设备。出门前请再次确认点位开放情况与商家携宠规则。</p><button class="back-text" data-action="delete-route">删除这条行程</button>`}
function profile(){return `<header class="header"><div class="logo">我和我的毛孩子</div><span class="small-badge">HELLO, PAWRENT</span></header><div class="profile-card"><img src="${photoSrc('golden')}" alt="豆包"><div><h2>${esc(state.pet.name)}</h2><p>${esc(state.pet.breed)} · ${esc(state.pet.size)} · 户外爱好者</p></div><button data-action="pet" aria-label="编辑宠物">${icon('edit')}</button></div><div class="stats"><button data-action="favorites"><b>${state.saved.length}</b>收藏的地点</button><button data-action="tab" data-value="trips"><b>${state.route?1:0}</b>出行计划</button><button data-action="orders"><b>${state.bookings.length}</b>我的预约</button></div><div><button class="menu-row" data-action="pet">${icon('paw')}宠物档案<span>完善偏好，推荐更合适</span>${icon('chevron')}</button><button class="menu-row" data-action="favorites">${icon('heart')}我的收藏${icon('chevron')}</button><button class="menu-row" data-action="orders">${icon('ticket')}我的套餐预约${icon('chevron')}</button><button class="menu-row" data-action="merchant">${icon('coffee')}我是宠物友好商家${icon('chevron')}</button></div><div class="prototype-note"><b>PetAccess · 带它一起出门</b>当前为产品交互演示，地点、商家规则、价格与库存均为示例。AI 使用本地演示逻辑，未接入模型、地图或支付服务。演示信息仅保存在当前设备。</div>`}
function render(){let page=$('#page'),scroll=page.scrollTop;page.innerHTML=state.tab==='home'?home():state.tab==='map'?`<h1 class="page-title">把附近，走成风景</h1><p class="page-desc">每一个标记，都是欢迎毛孩子的地方。</p>${mapHTML()}<div class="section-head"><h2>附近探索</h2><span class="small-badge">${places.length} 个友好地点</span></div>${places.map(p=>listCard(p)).join('')}`:state.tab==='trips'?itinerary():state.tab==='favorites'?`<button class="back-text" data-action="tab" data-value="me">${icon('back')}返回我的</button><h1 class="page-title">收藏的小美好</h1><p class="page-desc">下次出门，就从这里选一个。</p>${state.saved.length?grid(places.filter(p=>state.saved.includes(p.id))):'<div class="empty-state"><h3>还没有收藏的地点</h3><p>点击地点照片上的爱心，记下想去的地方。</p><button class="primary" data-action="tab" data-value="home">去发现好去处</button></div>'}`:profile();$('#floating').innerHTML=state.tab==='me'?'':`<button class="float-ai" data-action="ai"><span class="ai-logo">${brandLogo()}</span>AI 带你和它出发 ${icon('spark','spark')}</button>`;$('#bottom-nav').innerHTML=[['home','home','发现'],['map','map','地图'],['trips','route','行程'],['me','user','我的']].map(([id,ic,label])=>`<button class="${(state.tab===id||id==='me'&&state.tab==='favorites')?'active':''}" data-action="tab" data-value="${id}" aria-label="${label}" ${state.tab===id?'aria-current="page"':''}>${icon(ic)}${label}</button>`).join('');syncSearchView();page.scrollTop=scroll;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function close(){state.modal=null;$('#overlay').innerHTML=''}
function sheet(content,footer='',extra=''){ $('#overlay').innerHTML=`<div class="backdrop" data-action="close"></div><section class="sheet ${extra}" role="dialog" aria-modal="true"><div class="sheet-handle"></div>${content}${footer?`<div class="sheet-footer">${footer}</div>`:''}</section>`; }
function sheetHead(title){return `<div class="sheet-header"><h2>${title}</h2><button class="close" data-action="close" aria-label="关闭">${icon('close')}</button></div>`}
function filterSheet(){state.modal='filter';state.draftFilters=[...state.filters];updateFilterSheet()}
function updateFilterSheet(){sheet(`<div class="sheet-body">${sheetHead('找到适合它的地方')}<p class="page-desc">先选好小偏好，再一起出门。</p>${[['携宠设施',state.category==='free'?['大型犬友好','提供水碗']:['大型犬友好','露台座位','提供水碗']],['出行偏好',['2 km 内','免费点位']]].map(([label,choices])=>`<div class="filter-group"><h3>${label}</h3><div class="choice-row">${choices.map(c=>`<button class="choice ${state.draftFilters.includes(c)?'selected':''}" data-action="draft-filter" data-value="${c}" aria-pressed="${state.draftFilters.includes(c)}">${c}</button>`).join('')}</div></div>`).join('')}</div>`,`<button class="reset" data-action="draft-reset">重置</button><button class="primary" data-action="apply-filters">查看好去处${icon('arrow')}</button>`)}
function detail(id){state.modal='detail';state.detailId=id;const p=places.find(p=>p.id===id);sheet(`<div class="detail-cover"><img src="${photoSrc(p.image)}" alt="${p.name}氛围图"><button class="close" data-action="close" aria-label="关闭">${icon('close')}</button><span class="place-kind ${p.free?'':'cafe'}">${icon(p.free?'tree':'coffee')}${p.free?'免费公共点位':'宠物友好咖啡馆'}${p.ad?' · 广告合作':''}</span></div><div class="detail-info"><h2>${p.name}</h2><div class="card-meta"><span class="star">★ ${p.rating}</span> ${p.reviews} 位宠友来过 · 距你 ${p.distance} km</div><p class="detail-description">${p.desc}</p><div class="rule-grid"><div class="rule">${icon('paw')}${p.small?'仅小型犬':'大型犬友好'}</div><div class="rule">${icon(p.free?'tree':'sun')}${p.free?'户外开放空间':'露台可落座'}</div><div class="rule">${icon('water')}${p.water?'设有饮水设施':'请自备饮水'}</div><div class="rule">${icon('shield')}需全程牵引</div></div><h3>出发前，先了解</h3><div class="detail-line">${icon('pin')}${p.address}</div><div class="detail-line">${icon('clock')}${p.hours}</div><div class="detail-line">${icon('info')}${p.rule}</div>${p.free?freeDetail(p):`<h3>这家店的人宠套餐</h3><div class="package"><h4>${packageInfo.title} · 2 人</h4><p>${packageInfo.food}<br>${packageInfo.pet}<br>不含宠物餐食 · 需提前预约</p><div class="package-bottom"><span class="price-main">¥ <b>${p.price}</b><del>¥${p.price+30}</del></span><span class="small-badge">预约到店</span></div><button class="primary package-book" data-action="booking" data-id="${p.id}">预约这份套餐${icon('arrow')}</button></div>`}<h3>宠友来过的足迹${p.free?' · 示例':''}</h3><div class="review"><img src="${photoSrc('dog')}" alt="宠友头像"><div><strong>小尾巴出走日记</strong><time>${p.update}</time><p>${p.review}</p></div></div><p class="notice">本页为产品演示，场景图与信息均为示例，请勿作为实际出行依据。${p.free?'公共点位仅提供信息，不提供预约或交易。':''}</p></div>`,`<button class="secondary" data-action="save-place" data-id="${p.id}" aria-label="收藏地点">${icon('heart')}</button><div class="detail-footer-meta">${p.free?'免费公共点位':'双人下午茶套餐'}<strong>${p.free?'免费开放':'¥'+p.price}</strong></div><button class="primary ${p.free?'':'orange'}" data-action="${p.free?'plan-from':'booking'}" data-id="${p.id}">${p.free?'规划散步路线':'预约套餐'}${icon('arrow')}</button>`)}
function routePointNotice(p){const r=latestCheckin(p.id);return !canPlan(p)?'<div class="route-status">该站携宠条件或现场状态有变化，请核实并重新规划。</div>':r?.access==='unsure'?'<div class="route-status">有待核实的本机反馈，出发前请确认现场规则。</div>':''}
function routeStops(p,c,photos=true){return `<div class="route-stop"><span class="stop-num">1</span><div class="stop-content"><div class="stop-time">14:00 – 15:30 · 慢慢遛狗</div><h4>${p.name} <span class="small-badge">免费</span></h4><p>${p.small?'小型犬友好':'大型犬友好'} · ${latestCheckin(p.id)?'有本机打卡反馈':'示例信息待核实'}<br>全程牵引，记得带好拾便袋。</p>${routePointNotice(p)}${photos?`<img src="${photoSrc(p.image)}" alt="${p.name}">`:''}</div></div><div class="route-transfer">${icon('walk')}预计车程 5 分钟 · 距离约 1.6 km（示意）</div><div class="route-stop"><span class="stop-num">2</span><div class="stop-content"><div class="stop-time">15:40 – 17:00 · ${c.free?'继续慢慢散步':'喝杯咖啡'}</div><h4>${c.name}${c.ad?'<span class="stop-ad">广告</span>':''}${c.free?' <span class="small-badge">免费</span>':''}</h4><p>${c.free?`${freeKinds[c.kind]} · ${c.small?'小型犬友好':'大型犬友好'}<br>自备饮水，保持牵引，放慢脚步。`:`露台接待${c.small?'小型犬':'大型犬'} · 提供水碗<br>可选下午茶 <span class="card-price">¥${c.price}</span>`}</p>${routePointNotice(c)}${photos?`<img src="${photoSrc(c.image)}" alt="${c.name}">`:''}</div></div>`}
function aiSecondStop(){const eligible=p=>p.free&&p.id!==state.selectedPark&&canPlan(p);return state.freeRoute?(places.find(p=>p.id===state.freeSecond&&eligible(p))||places.find(eligible)):places.find(p=>p.id===state.selectedCafe)}

function openAI(query){state.modal='ai';if(query){state.freeSecond=null;state.freeRoute=/免费.*(?:路线|散步)|(?:路线|散步).*免费|不花钱/.test(query);state.chatQuery=query;state.chatReady=true;const small=query.includes('小型犬')||query.includes('柯基')||state.pet.size==='小型犬';if(!canPlan(places.find(p=>p.id===state.selectedPark)))state.selectedPark=places.find(p=>p.free&&canPlan(p))?.id;if(small){state.selectedCafe='brunch'}else if(places.find(p=>p.id===state.selectedCafe)?.small){state.selectedCafe='cafe'}}renderAI();}
function routeAlternatives(p,c){const items=places.filter(x=>state.freeRoute?x.free&&x.id!==p.id&&x.id!==c.id&&canPlan(x):x.type==='cafe'&&x.id!==c.id&&(state.pet.size==='小型犬'||!x.small));return items.length?`<div class="alternative-head">${state.freeRoute?'第二站，也可以换成':'咖啡这一站，也可以换成'}<span>按宠物条件与点位状态筛选</span></div>${items.map(x=>`<div class="alternative"><img src="${photoSrc(x.image)}" alt="${x.name}"><div><h4>${x.name}${x.ad?' <span class="stop-ad">广告</span>':''}</h4><p>${x.free?`${freeKinds[x.kind]} · 免费`:`露台 · 水碗 · ¥${x.price}/套餐`}</p></div><button data-action="${x.free?'swap-free-stop':'swap-cafe'}" data-id="${x.id}">${x.free?'换这里':'换这家'}</button></div>`).join('')}`:''}
function renderAI(){let p=places.find(p=>p.id===state.selectedPark),c=aiSecondStop();const unavailable=state.chatReady&&(!canPlan(p)||(c?.free&&!canPlan(c))||!c);if(unavailable){state.chatReady=false;toast('适合的示例点位不足，请先核实状态或调整宠物条件')}const budget=(state.chatQuery.match(/(?:预算|不超过|以内|控制在)[^\d]{0,3}(\d+)/)||[])[1];let budgetText=budget&&Number(budget)<c?.price?`当前示例套餐 ¥${c.price}，超出了你提到的预算 ¥${budget}；可以只安排免费遛狗，不购买套餐。`:'';$('#overlay').innerHTML=`<section class="dialog-page" role="dialog" aria-modal="true" aria-label="AI 出行搭子"><header class="dialog-header"><div><span class="ai-logo">${brandLogo()}</span><div><h2>你的 AI 出行搭子</h2><p>先遛狗，再把生活过慢一点</p></div></div><button class="close" data-action="close" aria-label="关闭 AI">${icon('close')}</button></header><div class="chat-scroll" id="chat-scroll">${!state.chatReady?`<div class="ai-welcome">${unavailable?'<p class="route-status" role="status">当前适合它的示例点位不足两处。请先核实现场状态，或调整宠物档案后重新规划。</p>':''}<p class="hello">HI，${esc(state.pet.name)}的家长 👋</p><h2>今天，想和它<br><span>怎么度过？</span></h2><p>告诉我你在哪儿、带什么狗狗，<br>我来串起一段刚刚好的出行。</p>${petContext()}</div><p class="suggest-label">试试这样问我</p>${[['tree','周六下午带金毛，先遛狗再喝咖啡'],['coffee','找一家有露台、提供水碗的咖啡馆'],['route','福田出发，想要一条免费的散步路线']].map(([ic,q])=>`<button class="suggestion" data-action="ask" data-value="${q}">${icon(ic)}${q}${icon('arrow')}</button>`).join('')}`:`<div class="bubble-user">${esc(state.chatQuery)}</div><div class="answer-label"><span class="ai-logo">${brandLogo()}</span>给你和${esc(state.pet.name)}的小计划</div><p class="answer-text">${state.freeRoute?'给你安排两个适合它的免费点位，从选定地点出发，再去另一处公共空间散步。全程无需购买套餐，自备水和拾便袋就好。':'在福田，先给它一片草地，再给你一杯咖啡。挑了适合携宠的两站，慢慢走，不赶路。'}</p>${budgetText?`<p class="route-hint">${esc(budgetText)}</p>`:''}<div class="route-card"><div class="route-card-head"><h3>和它一起，半日慢游</h3><p>福田区<span>·</span>约 3 小时<span>·</span>2 个地点</p></div>${routeStops(p,c)}<div class="route-actions"><button class="secondary" data-action="save-route">${state.route?'更新行程':'保存行程'}</button><button class="primary" data-action="${c.free?'navigation':'booking'}" data-id="${c.id}">${c.free?'查看散步路线':'预约咖啡 ¥'+c.price}</button></div></div><p class="route-hint">${icon('info')} ${state.freeRoute?'公共点位仅提供信息，无需预约。':'咖啡馆可选购套餐，不购买也可按商家规则消费。'}<br>路线与车程为演示，出行前需确认。${state.freeRoute?'':'广告商家已标注。'}</p>${routeAlternatives(p,c)}<button class="back-text" data-action="swap-park">${icon('refresh')}换一个散步地点</button><button class="back-text" data-action="navigation">${icon('map')}查看两站路线</button>`}</div><form class="chat-input-wrap" id="chat-form"><div class="chat-input"><input name="message" aria-label="告诉 AI 你的出行想法" placeholder="例如：带金毛在福田玩一个下午" autocomplete="off" required><button aria-label="发送消息">${icon('send')}</button></div><p class="chat-caption">AI 路线交互演示 · 基于本地示例库生成，未接入真实模型</p></form></section>`;}
function saveRoute(){state.route={park:state.selectedPark,cafe:aiSecondStop().id,savedAt:new Date().toISOString()};persist('route',state.route);toast('已保存到「行程」，下次出门直接看');}
function booking(id){const p=places.find(p=>p.id===id);if(!p||p.free)return;if(p.small&&state.pet.size!=='小型犬'){toast('这家暂仅接待小型犬，请选择大型犬友好的咖啡馆');return}state.bookingReturn=state.modal;state.modal='booking';state.bookingId=id;const now=new Date();let tomorrow=new Date(now.getFullYear(),now.getMonth(),now.getDate()+1);const date=new Date(tomorrow.getTime()-tomorrow.getTimezoneOffset()*60000).toISOString().slice(0,10);sheet(`<div class="sheet-body">${sheetHead('留一个，和它的下午')}<div class="booking-summary"><img src="${photoSrc(p.image)}" alt="${p.name}"><div><h3>${p.name}</h3><p>${packageInfo.title} · 2 人<br>${packageInfo.food}<br>${packageInfo.pet}</p></div></div><form id="booking-form"><div class="form-inline"><div class="form-field"><label for="book-date">到店日期</label><input id="book-date" type="date" name="date" value="${date}" min="${date}" required></div><div class="form-field"><label for="book-time">到店时间</label><select id="book-time" name="time"><option>14:00</option><option selected>15:40</option><option>16:30</option><option>17:00</option></select></div></div><div class="form-inline"><div class="form-field"><label for="book-people">到店人数</label><select id="book-people" name="people"><option>1 人</option><option selected>2 人</option></select></div><div class="form-field"><label for="book-dog">携带宠物</label><select id="book-dog" name="dog"><option>${esc(state.pet.name)} · ${esc(state.pet.size)}</option></select></div></div><div class="rule">${icon('shield')}${p.small?'小型犬':'大型犬'}可在露台落座 · 宠物需全程牵引</div><div class="booking-total"><span>套餐合计 <span style="color:var(--muted);font-size:11px">1 份双人套餐</span></span><strong>¥${p.price}</strong></div><button class="primary orange" type="submit">确认演示预约 ${icon('arrow')}</button><p class="notice">本次为演示预约，不扣费、不联系商家、不占用真实座位。无需填写手机号。</p></form></div>`)}
function submitBooking(form){const p=places.find(p=>p.id===state.bookingId);const data=Object.fromEntries(new FormData(form));const order={...data,place:p.id,id:Date.now(),price:p.price};state.bookings.unshift(order);persist('bookings',state.bookings);state.modal='success';sheet(`<div class="sheet-body">${sheetHead('预约已记录')}<div class="success"><div class="success-icon">${icon('check')}</div><h2>这个下午，有着落了。</h2><p>已为你记录一份演示预约，<br>和${esc(state.pet.name)}一起期待下一次出门吧。</p><div class="booking-summary"><img src="${photoSrc(p.image)}" alt="${p.name}"><div><h3>${p.name}</h3><p>${esc(order.date)} · ${esc(order.time)} · ${esc(order.people)}<br>露台座位 · 双人下午茶 ¥${p.price}</p></div></div><span class="small-badge">演示预约 · 无真实订单</span><button class="primary" data-action="view-orders">查看我的预约</button><p class="notice">未产生支付或真实商家预约。</p></div></div>`);render()}
function orders(){state.modal='orders';sheet(`<div class="sheet-body">${sheetHead('我的套餐预约')}${state.bookings.length?state.bookings.map(o=>{let p=places.find(p=>p.id===o.place);return `<div class="package" style="margin-bottom:12px"><div class="section-head"><h3 style="font-size:13px">${p.name}</h3><span class="small-badge">${o.cancelled?'已取消':'演示预约'}</span></div><p>双人下午茶 · ¥${o.price}<br>${esc(o.date)} · ${esc(o.time)} · ${esc(o.people)}<br>订单演示编号 PA${String(o.id).slice(-8)}</p>${o.cancelled?'':`<button class="back-text" data-action="cancel-order" data-id="${o.id}">取消这份预约</button>`}</div>`}).join(''):'<div class="empty-state"><h3>还没有预约</h3><p>去挑一家欢迎毛孩子的咖啡馆吧。</p><button class="primary" data-action="go-cafes">发现咖啡馆</button></div>'}<p class="notice">这里仅保存演示记录，不产生真实订单或支付。</p></div>`)}
function petSheet(){state.modal='pet';sheet(`<div class="sheet-body">${sheetHead('认识一下你的毛孩子')}<p class="page-desc">让每一次推荐，更懂它一点。</p><form id="pet-form"><div class="form-field"><label for="pet-name">它的名字</label><input id="pet-name" name="name" value="${esc(state.pet.name)}" required maxlength="12"></div><div class="form-field"><label for="pet-breed">品种</label><input id="pet-breed" name="breed" value="${esc(state.pet.breed)}" required maxlength="20"></div><div class="form-field"><label for="pet-size">体型</label><select id="pet-size" name="size">${['大型犬','中型犬','小型犬'].map(s=>`<option ${s===state.pet.size?'selected':''}>${s}</option>`).join('')}</select></div><button class="primary">保存宠物档案${icon('check')}</button><p class="notice">档案仅保存在本机浏览器，用于此原型内的推荐演示。</p></form></div>`)}
function navigation(){if(state.modal!=='navigation')state.navFromAI=state.modal==='ai';state.modal='navigation';let p=places.find(p=>p.id===(state.navFromAI?state.selectedPark:(state.route?.park||state.selectedPark))),c=state.navFromAI?aiSecondStop():places.find(p=>p.id===(state.route?.cafe||aiSecondStop().id));sheet(`<div class="sheet-body">${sheetHead('把两站，连成一个下午')}<p class="navigation-overview">${p.name} → ${c.name}<br>地点和车程为交互示意，未接入真实地图导航。</p>${mapHTML([p,c])}${routeStops(p,c,false)}<div style="margin-top:22px"><button class="primary" data-action="next-stop">${state.navStep===1?'我已到达第一站，查看下一站':'第二站：'+c.name}${icon('arrow')}</button><button class="back-text" data-action="stop-detail" data-id="${state.navStep===1?p.id:c.id}">${icon('pin')}查看${state.navStep===1?'第一':'第二'}站详情</button></div><p class="notice">出发前请通过真实地图核实目的地与携宠规则。</p></div>`)}
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='search-form'){updateSearch(f.elements.namedItem('search'),true)}if(f.id==='chat-form'){const q=f.message.value.trim();if(!q)return;state.freeRoute=/免费.*(?:路线|散步)|(?:路线|散步).*免费|不花钱/.test(q);state.chatQuery=q;state.chatReady=true;state.selectedCafe=q.includes('预算')&&q.includes('60')?'coffee':state.pet.size==='小型犬'?'brunch':'cafe';if(q.includes('郊野')||q.includes('梅林'))state.selectedPark='trail';if(!canPlan(places.find(p=>p.id===state.selectedPark)))state.selectedPark=places.find(p=>p.free&&canPlan(p))?.id;renderAI()}if(f.id==='checkin-form')submitCheckin(f);if(f.id==='booking-form')submitBooking(f);if(f.id==='pet-form'){state.pet=Object.fromEntries(new FormData(f));persist('pet',state.pet);state.chatReady=false;close();render();toast('记住啦，下次会按它的体型推荐')}});
document.addEventListener('input',e=>{if(e.target.name==='search'&&!e.isComposing)updateSearch(e.target)});
document.addEventListener('compositionend',e=>{if(e.target.name==='search')updateSearch(e.target)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Enter'&&e.target.classList.contains('card-info'))detail(e.target.dataset.id)});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action:a,id,value:v}=b.dataset;
if(a==='clear-search'){const input=$('#search-form input');input.value='';updateSearch(input);input.focus({preventScroll:true});$('#page').scrollTop=0}
if(a==='checkin')checkinSheet(id);
if(a==='free-kind'){state.freeKind=v;render();document.querySelector(`.free-kind[data-value="${v}"]`)?.focus({preventScroll:true});$('#discover-status').textContent=`${v==='all'?'全部免费点位':freeKinds[v]}，找到 ${filteredPlaces().length} 个地点`}
if(a==='start-free-route'||a==='start-cafe-route'){const p=places.find(p=>p.id===id);if(!canPlan(p)){toast('点位状态或宠物条件有变化，请重新选择');return}state.selectedPark=id;openAI(`从${p.name}出发，带${state.pet.name}${a==='start-free-route'?'安排免费的散步路线':'先遛狗再喝咖啡'}`)}
if(a==='close')close();
if(a==='tab'){close();state.tab=v;render();$('#page').scrollTop=0}
if(a==='location'){state.modal='location';sheet(`<div class="sheet-body">${sheetHead('发现深圳的友好角落')}<p class="page-desc">首版先从福田出发，慢慢拓展出行半径。</p><div class="choice-row"><button class="choice selected" data-action="choose-location">${icon('pin')}深圳 · 福田</button></div><p class="notice">南山、罗湖等区域将在后续版本中逐步加入。</p></div>`)}
if(a==='choose-location'){close();toast('已选择深圳 · 福田')}
if(a==='category')selectCategory(v,b.classList.contains('quicklink')?'quick':'all');
if(a==='deals')selectCategory('deals','deals');
if(a==='toggle-map'){state.map=!state.map;render()}
if(a==='quick-filter'){state.filters=state.filters.includes(v)?state.filters.filter(f=>f!==v):[...state.filters,v];render()}
if(a==='filters')filterSheet();
if(a==='draft-filter'){state.draftFilters=state.draftFilters.includes(v)?state.draftFilters.filter(f=>f!==v):[...state.draftFilters,v];updateFilterSheet()}
if(a==='draft-reset'){state.draftFilters=[];updateFilterSheet()}
if(a==='apply-filters'){state.filters=[...state.draftFilters];close();render()}
if(a==='reset-filters'){state.filters=[];state.query='';selectCategory(state.category==='free'?'free':'all','all')}
if(a==='detail'||a==='stop-detail')detail(id);
if(a==='save-place'){state.saved=state.saved.includes(id)?state.saved.filter(i=>i!==id):[...state.saved,id];persist('saved',state.saved);render();if(state.modal==='detail')detail(id);toast(state.saved.includes(id)?'已收藏，记下这个好去处':'已取消收藏')}
if(a==='ai')openAI();
if(a==='ask')openAI(v);
if(a==='plan-from')routeOptions(id);
if(a==='swap-free-stop'){const p=places.find(p=>p.id===id);if(p?.free&&canPlan(p)){state.freeSecond=id;renderAI();toast('已更换第二个免费点位')}}
if(a==='swap-cafe'){state.freeRoute=false;state.selectedCafe=id;renderAI();toast('已更换咖啡馆，前面的散步安排保留')}
if(a==='swap-park'){const candidates=places.filter(p=>p.free&&canPlan(p)&&p.id!==aiSecondStop()?.id);const index=candidates.findIndex(p=>p.id===state.selectedPark);state.selectedPark=candidates[(index+1)%candidates.length]?.id;renderAI();toast('已按宠物条件与本机反馈更换散步地点')}
if(a==='save-route'){saveRoute();render()}
if(a==='delete-route'){state.route=null;persist('route',null);render();toast('行程已删除，可以重新规划')}
if(a==='booking')booking(id);
if(a==='orders'||a==='view-orders')orders();
if(a==='cancel-order'){const o=state.bookings.find(o=>String(o.id)===id);if(o){o.cancelled=true;persist('bookings',state.bookings);orders();toast('已取消演示预约')}}
if(a==='go-cafes'){close();state.tab='home';state.category='cafe';render();$('#page').scrollTop=380}
if(a==='pet')petSheet();
if(a==='favorites'){close();state.tab='favorites';render();$('#page').scrollTop=0}
if(a==='navigation'){state.navStep=1;navigation()}
if(a==='next-stop'){state.navStep=2;navigation();toast('第一站已到达，下一站继续享受下午')}
if(a==='merchant'){state.modal='merchant';sheet(`<div class="sheet-body">${sheetHead('让更多毛孩子，找到你')}<p class="page-desc">PetAccess 宠物友好商家计划</p><div class="filter-group"><h3>基础收录免费</h3><p class="notice">展示门店信息、携宠规则、设施和营业时间，让宠友在地图和推荐中发现你。</p></div><div class="filter-group"><h3>套餐预约，按成交计佣</h3><p class="notice">上线人宠套餐或露台座位预约，演示方案为成交收取 10% 佣金。</p></div><div class="filter-group"><h3>推广位置明确标注</h3><p class="notice">商家可选择信息流展示或专题推广。推广展示需满足用户的宠物条件，并标注广告。</p></div><p class="notice">商家入驻为下一步建设内容，当前原型展示消费者发现与预约流程。</p><button class="primary" data-action="close">了解了 ${icon('check')}</button></div>`)}
});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=el.dataset.icon==='brand'?brandLogo():icon(el.dataset.icon));render();
